    private ?InsightTimeRangeWithStep $timeRangeOverride = null;

    public static function make(): self
    {
        return new self;
    }

    public function formatPlan(InsightRunFormatPlan $formatPlan): self
    {
        $this->formatPlan = $formatPlan;

        return $this;
    }

    public function timeRangeOverride(InsightTimeRangeWithStep $timeRangeOverride): self
    {
        $this->timeRangeOverride = $timeRangeOverride;

        return $this;
    }

    public function build(): InsightRunDto
    {
        $values = array_filter([
            'formatPlan' => $this->formatPlan,
            'timeRangeOverride' => $this->timeRangeOverride,
        ], static fn (mixed $value): bool => $value !== null);

        return new InsightRunDto($values);
    }
}
